import { i as superValidate, n as message, r as setError } from "../../../chunks/client2.js";
import "../../../chunks/dist3.js";
import { t as zod } from "../../../chunks/adapters.js";
import { t as APIError } from "../../../chunks/error.js";
import { t as auth } from "../../../chunks/auth.js";
import { t as redirect } from "../../../chunks/server.js";
import { z } from "zod/v4";
//#region src/routes/login/schema.ts
var loginSchema = z.object({
	email: z.email({ error: "Invalid email address" }),
	password: z.string().min(8, { error: "Password must be at least 8 characters" })
});
//#endregion
//#region src/routes/login/+page.server.ts
var load = async ({ locals, parent }) => {
	if (locals.user) return redirect(302, "/dashboard");
	return { form: await superValidate(zod(loginSchema)) };
};
var actions = { login: async (event) => {
	const form = await superValidate(event.request, zod(loginSchema));
	if (!form.valid) return message(form, {
		type: "error",
		text: "Please Check the form}"
	}, { status: 500 });
	const { email, password } = form.data;
	try {
		if (!(await auth.api.signInEmail({ body: {
			email,
			password,
			callbackURL: "/auth/verification-success"
		} })).user) {
			setError(form, "email", "Invalid email or password");
			setError(form, "password", "Invalid email or password");
			return message(form, {
				type: "error",
				text: "An error occurred while logging in"
			}, { status: 500 });
		}
		return message(form, {
			type: "success",
			text: "Sign Up Successful!"
		});
	} catch (error) {
		if (error instanceof APIError) return message(form, {
			type: "error",
			text: error?.message
		}, { status: 500 });
		return message(form, {
			type: "error",
			text: "Registration Failed"
		}, { status: 500 });
	}
} };
//#endregion
export { actions, load };
